 static NativeCompletion? completion;static LeaseBag leases=new();static bool building;static double started;static int mainThread;static NativeVisualLayer? visuals;static NavigationLayer? navigation;static readonly List<AsyncOperation> unloads=new();static Texture2D? mapTexture;static Sprite? mapSprite;static HNSMapProfile? mapProfile;static List<Scene> oldScenes=new();static int sceneGeneration;
 internal static void Preflight(){if(!Repositories.Ensure())throw new InvalidOperationException(Repositories.Reason);if(File.ReadAllBytes(Path.Combine(Identity.Folder,"reserve-map.rgba")).Length!=512*512*4)throw new InvalidDataException("Minimap texture length mismatch");var task=new NativeCompletion();using var root=new NativeRoot(task);if(!task.TrySetResult(null!))throw new InvalidOperationException("Native scene task bridge failed");if(NavMesh.GetSettingsCount()<1)throw new InvalidOperationException("No native NavMesh settings available");}
 internal static NativeTask Begin(LoadSceneMode mode){if(building&&completion!=null)return completion.Task;if(Ready&&Scene.IsValid()&&Scene.isLoaded)return NativeTask.CompletedTask;if(WorldBridge.ActiveCount>0)throw new InvalidOperationException("Another Reserve world is still alive");releaseAt=-1;Release();Preflight();mainThread=Thread.CurrentThread.ManagedThreadId;Gate=new NativeBuildBarrier(()=>{if(Thread.CurrentThread.ManagedThreadId!=mainThread)throw new InvalidOperationException("Scene operation is not on Unity thread");});completion=new NativeCompletion();leases.Keep(completion);building=true;Failed=false;started=Time.realtimeSinceStartupAsDouble;sceneGeneration++;Trace.Data["status"]="BUILDING_RESERVE";Trace.Data["sceneGeneration"]=sceneGeneration;
 for(int i=0;i<SceneManager.sceneCount;i++){var s=SceneManager.GetSceneAt(i);if(s.IsValid()&&s.isLoaded&&s.name!="DontDestroyOnLoad")oldScenes.Add(s);}Scene=SceneManager.CreateScene(Identity.Map);if(!Scene.IsValid()||!Scene.isLoaded)throw new InvalidOperationException("Own runtime scene creation failed");SceneManager.SetActiveScene(Scene);
