 static Shader? ChooseShader(){foreach(string name in new[]{"Universal Render Pipeline/Lit","Standard","HDRP/Lit","Legacy Shaders/Diffuse"}){var s=Shader.Find(name);if(s!=null&&s.isSupported){Trace.Data["selectedShader"]=name;return s;}}return null;}
 static void CreateMap(){var raw=File.ReadAllBytes(Path.Combine(Identity.Folder,"reserve-map.rgba"));mapTexture=new Texture2D(512,512,TextureFormat.RGBA32,false);mapTexture.name="Reserve map";mapTexture.LoadRawTextureData((Il2CppStructArray<byte>)raw);mapTexture.Apply(false,false);mapTexture.wrapMode=TextureWrapMode.Clamp;mapTexture.filterMode=FilterMode.Bilinear;mapSprite=Sprite.Create(mapTexture,new Rect(0,0,512,512),new Vector2(.5f,.5f),100,0,SpriteMeshType.FullRect);mapSprite.name="Reserve map";mapProfile=ScriptableObject.CreateInstance<HNSMapProfile>();mapProfile.name="Frontier Reserve Map";mapProfile.CustomLayers=new Il2CppSystem.Collections.Generic.List<CustomLayer>();mapProfile.Init(mapSprite,new Vector2(512,512),new Color(.08f,.09f,.1f,1),new Bounds(new Vector3(0,0,24),new Vector3(144,12,184)));
 NavigationConfig=ScriptableObject.CreateInstance<HNSSceneConfiguration>();NavigationConfig.name="Frontier Reserve Navigation";NavigationConfig.overrideMinimapSettings=true;NavigationConfig.useMinimap=true;NavigationConfig.minimapProfile=mapProfile;NavigationConfig.minimapRadius=100;NavigationConfig.minimapScale=1;NavigationConfig.showMinimapBounds=true;NavigationConfig.overrideRadarSettings=false;NavigationConfig.overrideCompassBarSettings=false;NavigationConfig.overrideIndicatorSettings=false;leases.Keep(mapTexture);leases.Keep(mapSprite);leases.Keep(mapProfile);leases.Keep(NavigationConfig);}
